package main

import (
	"bufio"
	"bytes"
	"crypto/chacha20poly1305"
	"crypto/ecdh"
	"crypto/hmac"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"io"
	"math/big"
	"os"
	"strconv"
	"strings"

	"golang.org/x/crypto/curve25519"
	"golang.org/x/crypto/hkdf"
	"golang.org/x/crypto/scrypt"
	"golang.org/x/crypto/ssh"
)

const (
	fileIntro                = "age-encryption.org/v1\n"
	defaultScryptWorkFactor  = 18
	chunkSize                = 64 * 1024
	x25519Label              = "age-encryption.org/v1/X25519"
	scryptLabel              = "age-encryption.org/v1/scrypt"
	sshED25519Label          = "age-encryption.org/v1/ssh-ed25519"
	sshRSALabel              = "age-encryption.org/v1/ssh-rsa"
	headerLabel              = "header"
	payloadLabel             = "payload"
	armorType                = "AGE ENCRYPTED FILE"
)

var (
	errMissingIdentities      = errors.New("missing identities")
	errPassphraseWithIdentities = errors.New("passphrase file with identities")
	fieldModulus, _           = new(big.Int).SetString("7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed", 16)
	one                       = big.NewInt(1)
)

type Stanza struct {
	Type string
	Args []string
	Body []byte
}

type parsedAgeFile struct {
	HeaderBytes []byte
	Stanzas     []*Stanza
	MAC         []byte
	Payload     []byte
}

type Recipient interface {
	Wrap(fileKey []byte) (*Stanza, error)
}

type Identity interface {
	Unwrap(stanza *Stanza) ([]byte, bool, error)
	Recipient() (Recipient, error)
}

type X25519Recipient struct {
	publicKey [32]byte
}

type X25519Identity struct {
	secretKey [32]byte
	publicKey [32]byte
}

type ScryptRecipient struct {
	passphrase string
	workFactor int
}

type SSHRSARecipient struct {
	tag string
	key *rsa.PublicKey
}

type SSHRSAIdentity struct {
	tag string
	key *rsa.PrivateKey
}

type SSHEd25519Recipient struct {
	tag         string
	publicSSH   ssh.PublicKey
	publicCurve [32]byte
}

type SSHEd25519Identity struct {
	tag         string
	privateKey  [32]byte
	publicCurve [32]byte
}

func NewScryptRecipient(passphrase string, workFactor int) *ScryptRecipient {
	return &ScryptRecipient{passphrase: passphrase, workFactor: workFactor}
}

func Encrypt(in io.Reader, out io.Writer, recipients []Recipient, armor bool) error {
	fileKey := make([]byte, 16)
	if _, err := rand.Read(fileKey); err != nil {
		return err
	}

	stanzas := make([]*Stanza, 0, len(recipients))
	for _, recipient := range recipients {
		stanza, err := recipient.Wrap(fileKey)
		if err != nil {
			return err
		}
		stanzas = append(stanzas, stanza)
	}

	var raw bytes.Buffer
	if err := writeHeader(&raw, fileKey, stanzas); err != nil {
		return err
	}
	if err := encryptPayload(fileKey, in, &raw); err != nil {
		return err
	}

	if armor {
		block := &pem.Block{Type: armorType, Bytes: raw.Bytes()}
		return pem.Encode(out, block)
	}
	_, err := out.Write(raw.Bytes())
	return err
}

func Decrypt(in io.Reader, out io.Writer, identities []Identity) error {
	data, err := io.ReadAll(in)
	if err != nil {
		return err
	}
	raw, err := decodeArmorIfNeeded(data)
	if err != nil {
		return err
	}
	parsed, err := parseAgeFile(raw)
	if err != nil {
		return fmt.Errorf("failed to read header: %w", err)
	}

	fileKey, err := recoverFileKey(parsed, identities, "Enter passphrase:")
	if err != nil {
		return err
	}
	return decryptPayload(fileKey, parsed.Payload, out)
}

func decodeArmorIfNeeded(data []byte) ([]byte, error) {
	if !bytes.HasPrefix(data, []byte("-----BEGIN AGE ENCRYPTED FILE-----")) {
		return data, nil
	}
	block, rest := pem.Decode(data)
	if block == nil || block.Type != armorType {
		return nil, errors.New("invalid armored age file")
	}
	if len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("invalid armored age file")
	}
	return block.Bytes, nil
}

func parseAgeFile(data []byte) (*parsedAgeFile, error) {
	br := bufio.NewReader(bytes.NewReader(data))
	intro, err := br.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			return nil, fmt.Errorf("parsing age header: unexpected intro: %q", intro)
		}
		return nil, err
	}
	if intro != fileIntro {
		return nil, fmt.Errorf("parsing age header: unexpected intro: %q", intro)
	}

	var header bytes.Buffer
	header.WriteString(intro)
	var stanzas []*Stanza

	line, err := br.ReadString('\n')
	if err != nil {
		return nil, fmt.Errorf("parsing age header: %w", err)
	}

	for {
		if strings.HasPrefix(line, "--- ") {
			macText := strings.TrimSuffix(strings.TrimPrefix(line, "--- "), "\n")
			mac, err := base64.RawStdEncoding.DecodeString(macText)
			if err != nil {
				return nil, fmt.Errorf("parsing age header: invalid header MAC")
			}
			payload, err := io.ReadAll(br)
			if err != nil {
				return nil, err
			}
			return &parsedAgeFile{
				HeaderBytes: header.Bytes(),
				Stanzas:     stanzas,
				MAC:         mac,
				Payload:     payload,
			}, nil
		}
		if !strings.HasPrefix(line, "-> ") {
			return nil, fmt.Errorf("parsing age header: malformed recipient stanza")
		}
		header.WriteString(line)
		fields := strings.Fields(strings.TrimSpace(strings.TrimPrefix(line, "-> ")))
		if len(fields) == 0 {
			return nil, fmt.Errorf("parsing age header: malformed recipient stanza")
		}
		stanza := &Stanza{Type: fields[0], Args: append([]string(nil), fields[1:]...)}
		var body strings.Builder
		for {
			next, err := br.ReadString('\n')
			if err != nil {
				return nil, fmt.Errorf("parsing age header: %w", err)
			}
			if strings.HasPrefix(next, "-> ") || strings.HasPrefix(next, "--- ") {
				line = next
				break
			}
			header.WriteString(next)
			body.WriteString(strings.TrimSuffix(next, "\n"))
		}
		bodyBytes, err := base64.RawStdEncoding.DecodeString(body.String())
		if err != nil {
			return nil, fmt.Errorf("parsing age header: malformed recipient stanza")
		}
		stanza.Body = bodyBytes
		stanzas = append(stanzas, stanza)
	}
}

func writeHeader(out io.Writer, fileKey []byte, stanzas []*Stanza) error {
	var header bytes.Buffer
	header.WriteString(fileIntro)
	for _, stanza := range stanzas {
		header.WriteString("-> ")
		header.WriteString(stanza.Type)
		for _, arg := range stanza.Args {
			header.WriteByte(' ')
			header.WriteString(arg)
		}
		header.WriteByte('\n')
		encoded := base64.RawStdEncoding.EncodeToString(stanza.Body)
		for len(encoded) > 64 {

			header.WriteString(encoded[:64])
			header.WriteByte('\n')
			encoded = encoded[64:]
		}
		header.WriteString(encoded)
		header.WriteByte('\n')
	}

	mac := computeHeaderMAC(fileKey, header.Bytes())
	header.WriteString("--- ")
	header.WriteString(base64.RawStdEncoding.EncodeToString(mac))
	header.WriteByte('\n')
	_, err := out.Write(header.Bytes())
	return err
}

func recoverFileKey(parsed *parsedAgeFile, identities []Identity, prompt string) ([]byte, error) {
	hasScrypt := false
	for _, stanza := range parsed.Stanzas {
		if stanza.Type == "scrypt" {
			hasScrypt = true
			break
		}
	}

	if hasScrypt {
		if len(identities) > 0 {
			return nil, errPassphraseWithIdentities
		}
		pw, err := promptForDecryptionPassphrase(prompt + " ")
		if err != nil {
			return nil, fmt.Errorf("could not read passphrase: %v", err)
		}
		for _, stanza := range parsed.Stanzas {
			if stanza.Type != "scrypt" {
				continue
			}
			fileKey, err := unwrapScryptStanza(stanza, pw)
			if err != nil {
				continue
			}
			if hmac.Equal(parsed.MAC, computeHeaderMAC(fileKey, parsed.HeaderBytes)) {
				return fileKey, nil
			}
		}
		return nil, fmt.Errorf("incorrect passphrase")
	}

	if len(identities) == 0 {
		return nil, errMissingIdentities
	}

	for _, identity := range identities {
		for _, stanza := range parsed.Stanzas {
			fileKey, matched, err := identity.Unwrap(stanza)
			if !matched || err != nil {
				continue
			}
			if hmac.Equal(parsed.MAC, computeHeaderMAC(fileKey, parsed.HeaderBytes)) {
				return fileKey, nil
			}
		}
	}

	return nil, fmt.Errorf("no identity matched any of the recipients")
}

func computeHeaderMAC(fileKey []byte, header []byte) []byte {
	key := hkdfExpand(fileKey, nil, []byte(headerLabel), 32)
	mac := hmac.New(sha256.New, key)
	mac.Write(header)
	return mac.Sum(nil)
}

func encryptPayload(fileKey []byte, in io.Reader, out io.Writer) error {
	key := hkdfExpand(fileKey, nil, []byte(payloadLabel), chacha20poly1305.KeySize)
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return err
	}

	br := bufio.NewReader(in)
	var counter uint64
	for {
		chunk, last, err := readPlainChunk(br)
		if err != nil {
			return err
		}
		nonce := streamNonce(counter, last)
		sealed := aead.Seal(nil, nonce[:], chunk, nil)
		if _, err := out.Write(sealed); err != nil {
			return err
		}
		counter++
		if last {
			return nil
		}
	}
}

func decryptPayload(fileKey, payload []byte, out io.Writer) error {
	key := hkdfExpand(fileKey, nil, []byte(payloadLabel), chacha20poly1305.KeySize)
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return err
	}

	br := bufio.NewReader(bytes.NewReader(payload))
	var counter uint64
	for {
		chunk, last, err := readCipherChunk(br)
		if err != nil {
			return err
		}
		nonce := streamNonce(counter, last)
		opened, err := aead.Open(nil, nonce[:], chunk, nil)
		if err != nil {
			return err
		}
		if _, err := out.Write(opened); err != nil {
			return err
		}
		counter++
		if last {
			return nil
		}
	}
}

func readPlainChunk(br *bufio.Reader) ([]byte, bool, error) {
	buf := make([]byte, chunkSize)
	n, err := io.ReadFull(br, buf)
	switch err {
	case nil:
		_, peekErr := br.Peek(1)
		return buf[:n], peekErr == io.EOF, nil
	case io.EOF:
		return nil, true, nil
	case io.ErrUnexpectedEOF:
		return buf[:n], true, nil
	default:
		return nil, false, err
	}
}

func readCipherChunk(br *bufio.Reader) ([]byte, bool, error) {
	buf := make([]byte, chunkSize+chacha20poly1305.Overhead)
	n, err := io.ReadFull(br, buf)
	switch err {
	case nil:
		_, peekErr := br.Peek(1)
		if n < chacha20poly1305.Overhead {
			return nil, false, io.ErrUnexpectedEOF
		}
		return buf[:n], peekErr == io.EOF, nil
	case io.ErrUnexpectedEOF:
		if n < chacha20poly1305.Overhead {
			return nil, false, io.ErrUnexpectedEOF
		}
		return buf[:n], true, nil
	case io.EOF:
		return nil, false, io.ErrUnexpectedEOF
	default:
		return nil, false, err
	}
}

func streamNonce(counter uint64, last bool) [chacha20poly1305.NonceSize]byte {
	var nonce [chacha20poly1305.NonceSize]byte
	if last {
		nonce[0] = 1
	}
	binary.LittleEndian.PutUint64(nonce[4:], counter)
	return nonce
}

func hkdfExpand(secret, salt, info []byte, n int) []byte {
	out := make([]byte, n)
	if _, err := io.ReadFull(hkdf.New(sha256.New, secret, salt, info), out); err != nil {
		panic(err)
	}
	return out
}

func parseRecipient(recipient string) (Recipient, error) {
	recipient = strings.TrimSpace(recipient)
	switch {
	case strings.HasPrefix(strings.ToLower(recipient), "age1"):
		r, err := parseX25519Recipient(recipient)
		if err != nil {
			return nil, fmt.Errorf("unknown recipient type: %q", recipient)
		}
		return r, nil
	case strings.HasPrefix(recipient, "ssh-ed25519 "), strings.HasPrefix(recipient, "ssh-rsa "):
		return parseSSHRecipient(recipient)
	default:
		return nil, fmt.Errorf("unknown recipient type: %q", recipient)
	}
}

func parseRecipientFile(path string, stdinUsed bool) ([]Recipient, error) {
	data, err := readPathOrStdin(path, stdinUsed)
	if err != nil {
		return nil, err
	}
	var recipients []Recipient
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		r, err := parseRecipient(line)
		if err != nil {
			if strings.HasPrefix(line, "ssh-") {
				continue
			}
			return nil, err
		}
		recipients = append(recipients, r)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("%q: no recipients found", path)
	}
	return recipients, nil
}

func parseIdentityPath(path string, stdinUsed bool) ([]Identity, error) {
	data, err := readPathOrStdin(path, stdinUsed)
	if err != nil {
		return nil, err
	}
	return parseIdentityData(path, data)
}

func recipientsFromIdentityPath(path string, stdinUsed bool) ([]Recipient, error) {
	ids, err := parseIdentityPath(path, stdinUsed)
	if err != nil {
		return nil, err
	}
	recipients := make([]Recipient, 0, len(ids))
	for _, identity := range ids {
		recipient, err := identity.Recipient()
		if err != nil {
			return nil, err
		}
		recipients = append(recipients, recipient)
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("failed to read %q: no identities found", path)
	}
	return recipients, nil
}

func parseIdentityData(path string, data []byte) ([]Identity, error) {
	if looksLikeAgeFile(data) {
		raw, err := decodeArmorIfNeeded(data)

		if err == nil {
			parsed, err := parseAgeFile(raw)
			if err == nil {
				if fileKey, err := recoverFileKey(parsed, nil, fmt.Sprintf("Enter passphrase for identity file %q:", path)); err == nil {
					var clear bytes.Buffer
					if err := decryptPayload(fileKey, parsed.Payload, &clear); err != nil {
						return nil, err
					}
					return parseIdentityData(path, clear.Bytes())
				} else {
					return nil, err
				}
			}
		}
	}

	var identities []Identity
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(strings.ToUpper(line), "AGE-SECRET-KEY-1") {
			id, err := parseX25519Identity(line)
			if err != nil {
				return nil, err
			}
			identities = append(identities, id)
			continue
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(identities) > 0 {
		return identities, nil
	}

	if id, err := parseSSHIdentity(data); err == nil {
		return []Identity{id}, nil
	}
	return nil, fmt.Errorf("failed to read %q: no identities found", path)
}

func looksLikeAgeFile(data []byte) bool {
	data = bytes.TrimSpace(data)
	return bytes.HasPrefix(data, []byte(fileIntro)) || bytes.HasPrefix(data, []byte("-----BEGIN AGE ENCRYPTED FILE-----"))
}

func readPathOrStdin(path string, stdinUsed bool) ([]byte, error) {
	if path == "-" {
		if stdinUsed {
			return nil, fmt.Errorf("standard input is used for multiple purposes")
		}
		return io.ReadAll(os.Stdin)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return data, nil
}

func parseX25519Recipient(recipient string) (*X25519Recipient, error) {
	hrp, data, err := bech32Decode(recipient)
	if err != nil || hrp != "age" || len(data) != 32 {
		return nil, errors.New("invalid X25519 recipient")
	}
	var pk [32]byte
	copy(pk[:], data)
	return &X25519Recipient{publicKey: pk}, nil
}

func parseX25519Identity(identity string) (*X25519Identity, error) {
	hrp, data, err := bech32Decode(identity)
	if err != nil || hrp != "age-secret-key-" || len(data) != 32 {
		return nil, errors.New("invalid identity")
	}
	var sk [32]byte
	copy(sk[:], data)
	pub, err := curve25519.X25519(sk[:], curve25519.Basepoint)
	if err != nil {
		return nil, err
	}
	var pk [32]byte
	copy(pk[:], pub)
	return &X25519Identity{secretKey: sk, publicKey: pk}, nil
}

func (r *X25519Recipient) Wrap(fileKey []byte) (*Stanza, error) {
	curve := ecdh.X25519()
	eph, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	shared, err := eph.ECDH(mustX25519PublicKey(r.publicKey[:]))
	if err != nil {
		return nil, err
	}
	salt := append(append([]byte{}, eph.PublicKey().Bytes()...), r.publicKey[:]...)
	wrapKey := hkdfExpand(shared, salt, []byte(x25519Label), chacha20poly1305.KeySize)
	body, err := wrapFileKey(wrapKey, fileKey)
	if err != nil {
		return nil, err
	}
	return &Stanza{
		Type: "X25519",
		Args: []string{base64.RawStdEncoding.EncodeToString(eph.PublicKey().Bytes())},
		Body: body,
	}, nil
}

func (i *X25519Identity) Unwrap(stanza *Stanza) ([]byte, bool, error) {
	if stanza.Type != "X25519" || len(stanza.Args) != 1 {
		return nil, false, nil
	}
	eph, err := base64.RawStdEncoding.DecodeString(stanza.Args[0])
	if err != nil || len(eph) != 32 {
		return nil, true, errors.New("invalid ephemeral key")
	}
	shared, err := curve25519.X25519(i.secretKey[:], eph)
	if err != nil {
		return nil, true, err
	}
	salt := append(append([]byte{}, eph...), i.publicKey[:]...)
	wrapKey := hkdfExpand(shared, salt, []byte(x25519Label), chacha20poly1305.KeySize)
	fileKey, err := unwrapFileKey(wrapKey, stanza.Body)
	return fileKey, true, err
}

func (i *X25519Identity) Recipient() (Recipient, error) {
	return &X25519Recipient{publicKey: i.publicKey}, nil
}

func (r *ScryptRecipient) Wrap(fileKey []byte) (*Stanza, error) {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	wrapKey, err := scrypt.Key([]byte(r.passphrase), append([]byte(scryptLabel), salt...), 1<<r.workFactor, 8, 1, chacha20poly1305.KeySize)
	if err != nil {
		return nil, err
	}
	body, err := wrapFileKey(wrapKey, fileKey)
	if err != nil {
		return nil, err
	}
	return &Stanza{
		Type: "scrypt",
		Args: []string{
			base64.RawStdEncoding.EncodeToString(salt),
			strconv.Itoa(r.workFactor),
		},
		Body: body,
	}, nil
}

func unwrapScryptStanza(stanza *Stanza, passphrase string) ([]byte, error) {
	if stanza.Type != "scrypt" || len(stanza.Args) != 2 {
		return nil, errors.New("invalid scrypt stanza")
	}
	salt, err := base64.RawStdEncoding.DecodeString(stanza.Args[0])
	if err != nil {
		return nil, err
	}
	workFactor, err := strconv.Atoi(stanza.Args[1])
	if err != nil {
		return nil, err
	}
	wrapKey, err := scrypt.Key([]byte(passphrase), append([]byte(scryptLabel), salt...), 1<<workFactor, 8, 1, chacha20poly1305.KeySize)
	if err != nil {
		return nil, err
	}
	return unwrapFileKey(wrapKey, stanza.Body)
}

func wrapFileKey(wrapKey, fileKey []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	return aead.Seal(nil, make([]byte, chacha20poly1305.NonceSize), fileKey, nil), nil
}

func unwrapFileKey(wrapKey, body []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, make([]byte, chacha20poly1305.NonceSize), body, nil)
}

func mustX25519PublicKey(pub []byte) *ecdh.PublicKey {
	key, err := ecdh.X25519().NewPublicKey(pub)
	if err != nil {
		panic(err)
	}
	return key
}

func parseSSHRecipient(recipient string) (Recipient, error) {
	pub, _, _, _, err := ssh.ParseAuthorizedKey([]byte(recipient))
	if err != nil {
		return nil, err
	}
	tag := sshKeyTag(pub)
	switch pub.Type() {
	case ssh.KeyAlgoED25519:
		cryptoPub, ok := pub.(ssh.CryptoPublicKey)
		if !ok {
			return nil, errors.New("unsupported ssh recipient")
		}
		edPub, ok := cryptoPub.CryptoPublicKey().(interface{ Bytes() []byte })
		if !ok {
			return nil, errors.New("unsupported ssh recipient")
		}
		curvePub, err := ed25519PublicToCurve25519(edPub.Bytes())
		if err != nil {
			return nil, err
		}
		return &SSHEd25519Recipient{tag: tag, publicSSH: pub, publicCurve: curvePub}, nil
	case ssh.KeyAlgoRSA:
		cryptoPub, ok := pub.(ssh.CryptoPublicKey)
		if !ok {
			return nil, errors.New("unsupported ssh recipient")
		}
		rsaPub, ok := cryptoPub.CryptoPublicKey().(*rsa.PublicKey)
		if !ok || rsaPub.N.BitLen() < 2048 {
			return nil, errors.New("unsupported ssh recipient")
		}
		return &SSHRSARecipient{tag: tag, key: rsaPub}, nil
	default:
		return nil, errors.New("unsupported ssh recipient")
	}
}

func parseSSHIdentity(data []byte) (Identity, error) {
	raw, err := ssh.ParseRawPrivateKey(data)
	if err != nil {
		return nil, err
	}
	switch key := raw.(type) {
	case *rsa.PrivateKey:
		pub, err := ssh.NewPublicKey(&key.PublicKey)
		if err != nil {
			return nil, err
		}
		return &SSHRSAIdentity{tag: sshKeyTag(pub), key: key}, nil
	case interface{ Seed() []byte }:
		seed := key.Seed()
		pubBytes := make([]byte, 32)
		if rawKey, ok := raw.(interface{ Public() any }); ok {
			switch pub := rawKey.Public().(type) {
			case interface{ Bytes() []byte }:
				copy(pubBytes, pub.Bytes())
			}
		}
		if bytes.Equal(pubBytes, make([]byte, 32)) {
			return nil, errors.New("unsupported ssh identity")

		}
		curvePub, err := ed25519PublicToCurve25519(pubBytes)
		if err != nil {
			return nil, err
		}
		curvePriv := ed25519SeedToCurve25519(seed)
		pub, err := ssh.NewPublicKey(raw.(interface{ Public() any }).Public())
		if err != nil {
			return nil, err
		}
		return &SSHEd25519Identity{tag: sshKeyTag(pub), privateKey: curvePriv, publicCurve: curvePub}, nil
	default:
		return nil, errors.New("unsupported ssh identity")
	}
}

func (r *SSHRSARecipient) Wrap(fileKey []byte) (*Stanza, error) {
	body, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.key, fileKey, []byte(sshRSALabel))
	if err != nil {
		return nil, err
	}
	return &Stanza{Type: "ssh-rsa", Args: []string{r.tag}, Body: body}, nil
}

func (i *SSHRSAIdentity) Unwrap(stanza *Stanza) ([]byte, bool, error) {
	if stanza.Type != "ssh-rsa" || len(stanza.Args) != 1 {
		return nil, false, nil
	}
	if stanza.Args[0] != i.tag {
		return nil, false, nil
	}
	fileKey, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, i.key, stanza.Body, []byte(sshRSALabel))
	return fileKey, true, err
}

func (i *SSHRSAIdentity) Recipient() (Recipient, error) {
	return &SSHRSARecipient{tag: i.tag, key: &i.key.PublicKey}, nil
}

func (r *SSHEd25519Recipient) Wrap(fileKey []byte) (*Stanza, error) {
	curve := ecdh.X25519()
	eph, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	shared, err := eph.ECDH(mustX25519PublicKey(r.publicCurve[:]))
	if err != nil {
		return nil, err
	}
	salt := append(append([]byte{}, eph.PublicKey().Bytes()...), sshMarshalRecipient(r.publicSSH)...)
	wrapKey := hkdfExpand(shared, salt, []byte(sshED25519Label), chacha20poly1305.KeySize)
	body, err := wrapFileKey(wrapKey, fileKey)
	if err != nil {
		return nil, err
	}
	return &Stanza{
		Type: "ssh-ed25519",
		Args: []string{
			r.tag,
			base64.RawStdEncoding.EncodeToString(eph.PublicKey().Bytes()),
		},
		Body: body,
	}, nil
}

func (i *SSHEd25519Identity) Unwrap(stanza *Stanza) ([]byte, bool, error) {
	if stanza.Type != "ssh-ed25519" || len(stanza.Args) != 2 {
		return nil, false, nil
	}
	if stanza.Args[0] != i.tag {
		return nil, false, nil
	}
	eph, err := base64.RawStdEncoding.DecodeString(stanza.Args[1])
	if err != nil || len(eph) != 32 {
		return nil, true, errors.New("invalid ssh recipient")
	}
	shared, err := curve25519.X25519(i.privateKey[:], eph)
	if err != nil {
		return nil, true, err
	}
	pub, err := ssh.NewPublicKey(curve25519PublicToEd25519Placeholder(i.publicCurve))
	if err == nil {
		_ = pub
	}
	salt := append(append([]byte{}, eph...), sshMarshalTagOnly(i.tag)...)
	wrapKey := hkdfExpand(shared, salt, []byte(sshED25519Label), chacha20poly1305.KeySize)
	fileKey, err := unwrapFileKey(wrapKey, stanza.Body)
	return fileKey, true, err
}

func (i *SSHEd25519Identity) Recipient() (Recipient, error) {
	return nil, errors.New("ssh-ed25519 identity-to-recipient conversion unavailable")
}

func sshKeyTag(pub ssh.PublicKey) string {
	sum := sha256.Sum256(sshMarshalRecipient(pub))
	return base64.RawStdEncoding.EncodeToString(sum[:4])
}

func sshMarshalRecipient(pub ssh.PublicKey) []byte {
	return pub.Marshal()
}

func sshMarshalTagOnly(tag string) []byte {
	return []byte(tag)
}

func ed25519SeedToCurve25519(seed []byte) [32]byte {
	sum := sha256.Sum256(seed)
	var out [32]byte
	copy(out[:], sum[:])
	out[0] &= 248
	out[31] &= 127
	out[31] |= 64
	return out
}

func ed25519PublicToCurve25519(pub []byte) ([32]byte, error) {
	var out [32]byte
	if len(pub) != 32 {
		return out, errors.New("invalid ed25519 public key")
	}
	yBytes := append([]byte(nil), pub...)
	yBytes[31] &= 0x7f
	reverseBytes(yBytes)
	y := new(big.Int).SetBytes(yBytes)
	num := new(big.Int).Add(one, y)
	den := new(big.Int).Sub(one, y)
	den.Mod(den, fieldModulus)
	denInv := new(big.Int).ModInverse(den, fieldModulus)
	if denInv == nil {
		return out, errors.New("invalid ed25519 public key")
	}
	u := new(big.Int).Mul(num, denInv)
	u.Mod(u, fieldModulus)
	uBytes := u.FillBytes(make([]byte, 32))
	reverseBytes(uBytes)
	copy(out[:], uBytes)
	return out, nil
}

func reverseBytes(buf []byte) {
	for i, j := 0, len(buf)-1; i < j; i, j = i+1, j-1 {
		buf[i], buf[j] = buf[j], buf[i]
	}
}

func curve25519PublicToEd25519Placeholder(_ [32]byte) any { return nil }

