package main

import (
	"bufio"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
)

type multiFlag []string

func (m *multiFlag) String() string { return strings.Join(*m, ",") }

func (m *multiFlag) Set(v string) error {
	*m = append(*m, v)
	return nil
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	fs := flag.NewFlagSet("age", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {
		fmt.Fprint(os.Stdout, helpText)
	}

	var encrypt bool
	var decrypt bool
	var armor bool
	var passphrase bool
	var outputPath string
	var recipients multiFlag
	var recipientFiles multiFlag
	var identities multiFlag
	var plugins multiFlag
	var showVersion bool

	fs.BoolVar(&encrypt, "e", false, "")
	fs.BoolVar(&encrypt, "encrypt", false, "")
	fs.BoolVar(&decrypt, "d", false, "")
	fs.BoolVar(&decrypt, "decrypt", false, "")
	fs.BoolVar(&armor, "a", false, "")
	fs.BoolVar(&armor, "armor", false, "")
	fs.BoolVar(&passphrase, "p", false, "")
	fs.BoolVar(&passphrase, "passphrase", false, "")
	fs.StringVar(&outputPath, "o", "", "")
	fs.StringVar(&outputPath, "output", "", "")
	fs.Var(&recipients, "r", "")
	fs.Var(&recipients, "recipient", "")
	fs.Var(&recipientFiles, "R", "")
	fs.Var(&recipientFiles, "recipients-file", "")
	fs.Var(&identities, "i", "")
	fs.Var(&identities, "identity", "")
	fs.Var(&plugins, "j", "")
	fs.BoolVar(&showVersion, "version", false, "")

	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(os.Stdout, helpText)
			return 0
		}
		fmt.Fprintln(os.Stderr, err.Error())
		fmt.Fprint(os.Stdout, helpText)
		return 2
	}

	if showVersion {
		fmt.Println(versionString)
		return 0
	}

	inputs := fs.Args()
	if len(inputs) > 1 {
		reportError(
			fmt.Sprintf("too many INPUT arguments: %q %q", inputs[0], inputs[1]),
			"only a single input file may be specified at a time",
		)
		return 1
	}

	mode := "encrypt"
	explicitEncrypt := encrypt
	if decrypt {
		mode = "decrypt"
	}

	if encrypt && decrypt {
		reportError("-e/--encrypt can't be used with -d/--decrypt")
		return 1
	}
	if decrypt && passphrase {
		reportError("-p/--passphrase can't be used with -d/--decrypt",
			"note that password protected files are detected automatically")
		return 1
	}
	if decrypt && armor {
		reportError("-a/--armor can't be used with -d/--decrypt",
			"note that armored files are detected automatically, try again without -a/--armor")
		return 1
	}
	if passphrase && (len(recipients) > 0 || len(recipientFiles) > 0) {
		if len(recipients) > 0 {
			reportError("-p/--passphrase can't be combined with -r/--recipient")
		} else {
			reportError("-p/--passphrase can't be combined with -R/--recipients-file")
		}
		return 1
	}
	if mode == "encrypt" && !explicitEncrypt && (len(identities) > 0 || len(plugins) > 0) && !passphrase &&
		len(recipients) == 0 && len(recipientFiles) == 0 {
		reportError("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",
			"did you forget to specify -d/--decrypt?")
		return 1
	}
	if mode == "encrypt" && !explicitEncrypt && len(plugins) > 0 {
		reportError("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",
			"did you forget to specify -d/--decrypt?")
		return 1
	}

	if mode == "encrypt" {
		return runEncrypt(explicitEncrypt, armor, passphrase, outputPath, inputs, recipients, recipientFiles, identities, plugins)
	}
	return runDecrypt(outputPath, inputs, identities, plugins)
}

func runEncrypt(explicitEncrypt, armor, passphrase bool, outputPath string, inputs []string, recipientArgs, recipientFiles, identityPaths, plugins []string) int {
	inputPath := ""
	if len(inputs) == 1 {
		inputPath = inputs[0]
	}

	in, stdinUsed, err := openInput(inputPath)
	if err != nil {
		reportError(err.Error())
		return 1
	}
	defer closeIfNeeded(in, os.Stdin)

	if !armor && outputPath == "" && isTerminal(os.Stdout) {
		reportError("refusing to output binary to the terminal",
			"did you mean to use -a/--armor?",
			`force anyway with "-o -"`)
		return 1
	}

	out, err := openOutput(outputPath)
	if err != nil {
		reportError(err.Error())
		return 1
	}
	defer closeIfNeeded(out, os.Stdout)

	var recips []Recipient

	for _, arg := range recipientArgs {
		r, err := parseRecipient(arg)
		if err != nil {
			reportError(err.Error())
			return 1
		}
		recips = append(recips, r)
	}

	for _, path := range recipientFiles {
		rs, err := parseRecipientFile(path, stdinUsed)
		if err != nil {
			reportError(fmt.Sprintf("failed to parse recipient file %q: %v", path, err))
			return 1
		}
		recips = append(recips, rs...)
	}

	if explicitEncrypt {
		for _, path := range identityPaths {
			rs, err := recipientsFromIdentityPath(path, stdinUsed)
			if err != nil {
				reportError(fmt.Sprintf("reading %q: %v", path, err))
				return 1
			}
			recips = append(recips, rs...)
		}

		for i, plugin := range plugins {
			r, err := pluginRecipient(plugin)
			if err != nil {
				reportError(
					fmt.Sprintf("failed to wrap key for recipient #%d: %v", i, err),
					fmt.Sprintf("you might want to install the %q plugin", plugin),
					"visit https://age-encryption.org/awesome#plugins for a list of available plugins",
				)
				return 1
			}
			recips = append(recips, r)
		}
	}

	if passphrase {
		pw, autogenerated, err := promptForEncryptionPassphrase()
		if err != nil {
			reportError(fmt.Sprintf("could not read passphrase: %v", err))
			return 1
		}
		if autogenerated {
			fmt.Fprintf(os.Stderr, "age: using autogenerated passphrase %q\n", pw)
		}
		recips = append(recips, NewScryptRecipient(pw, defaultScryptWorkFactor))
	} else if len(recips) == 0 {
		reportError("missing recipients",
			"did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?")
		return 1
	}

