func TestProbePassphraseFile(t *testing.T) {
	data, err := os.ReadFile("/workspace/.probe/plain.pass.age")
	if err != nil {
		t.Fatal(err)
	}
	parsed, err := parseAgeFile(data)
	if err != nil {
		t.Fatal(err)
	}
	fileKey, err := unwrapScryptStanza(parsed.Stanzas[0], "million-mind-verify-swarm-cloud-today-field-obscure-orphan-pumpkin")
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("fileKey=%x\n", fileKey)
	fmt.Printf("mac-current=%x\n", computeHeaderMAC(fileKey, parsed.HeaderBytes))
	fmt.Printf("mac-file=%x\n", parsed.MAC)
	fmt.Printf("mac-hmac-only=%x\n", hmacSHA256(fileKey, parsed.HeaderBytes))
	candidates := []struct {
		name string
		salt []byte
		info []byte
	}{
		{"hkdf-empty", nil, nil},
		{"hkdf-header", nil, []byte("header")},
		{"hkdf-full-header", nil, []byte("age-encryption.org/v1/header")},
		{"hkdf-age-v1", nil, []byte("age-encryption.org/v1")},
		{"hkdf-intro-header", []byte(fileIntro), []byte("header")},
		{"hkdf-intro-full-header", []byte(fileIntro), []byte("age-encryption.org/v1/header")},
	}
	for _, candidate := range candidates {
		key := hkdfExpand(fileKey, candidate.salt, candidate.info, 32)
		fmt.Printf("%s=%x\n", candidate.name, hmacSHA256(key, parsed.HeaderBytes))
	}
	extra := map[string][]byte{
		"sha256(fileKey)":                      sha256Bytes(fileKey),
		"sha256(headerLabel||fileKey)":        sha256Bytes([]byte("header"), fileKey),
		"sha256(fileKey||headerLabel)":        sha256Bytes(fileKey, []byte("header")),
		"hmac(fileKey,headerLabel)":           hmacSHA256(fileKey, []byte("header")),
		"hmac(fileKey,fullHeaderLabel)":       hmacSHA256(fileKey, []byte("age-encryption.org/v1/header")),
		"hmac(fileKey,intro)":                 hmacSHA256(fileKey, []byte(fileIntro)),
		"sha256(fullHeaderLabel||fileKey)":    sha256Bytes([]byte("age-encryption.org/v1/header"), fileKey),
		"sha256(fileKey||fullHeaderLabel)":    sha256Bytes(fileKey, []byte("age-encryption.org/v1/header")),
	}
	for name, key := range extra {
		fmt.Printf("%s=%x\n", name, hmacSHA256(key, parsed.HeaderBytes))
	}
	key := hkdfExpand(fileKey, nil, []byte("age-encryption.org/v1/header"), 32)
	fmt.Printf("variant-no-intro=%x\n", hmacSHA256(key, parsed.HeaderBytes[len(fileIntro):]))
	fmt.Printf("variant-no-final-nl=%x\n", hmacSHA256(key, parsed.HeaderBytes[:len(parsed.HeaderBytes)-1]))
	fmt.Printf("variant-plus-delim=%x\n", hmacSHA256(key, append(append([]byte{}, parsed.HeaderBytes...), []byte(\"--- \")...)))
}

func sha256Bytes(parts ...[]byte) []byte {
	h := sha256.New()
	for _, part := range parts {
		h.Write(part)
	}
	return h.Sum(nil)
}

