func sha256Bytes(parts ...[]byte) []byte {
	h := sha256.New()
	for _, part := range parts {
		h.Write(part)
	}
	return h.Sum(nil)
}

func decryptPayloadWithKey(key, payload, nonce []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	chunk := payload
	return aead.Open(nil, nonce, chunk, nil)
}

func nonceCandidates() [][]byte {
	var out [][]byte
	out = append(out, make([]byte, 12))
	for i := 0; i < 12; i++ {
		n := make([]byte, 12)
		n[i] = 1
		out = append(out, n)
	}
	return out
}

func xNonceCandidates() [][]byte {
	var out [][]byte
	out = append(out, make([]byte, 24))
	for i := 0; i < 24; i++ {
		n := make([]byte, 24)
		n[i] = 1
		out = append(out, n)
	}
	return out
}

func decryptPayloadWithXKey(key, payload, nonce []byte) ([]byte, error) {
	aead, err := chacha20poly1305.NewX(key)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, nonce, payload, nil)
}
